import axios from 'axios';
import { defineComponent } from 'vue';

import { IGameServerResponse, RESULT_CODES } from '@game-studio/server-comms';
import { ICurrencySettings } from '@game-studio/utilities';

import { gameConfig } from '../../models/config-model';
import { inversifyContainer } from '../../inversify/container';
import { userModel } from '../../models/user';
import { environment } from '../../services/environment';
import { eventEmitter } from '../../services/event-emitter';
import { queryStringParams } from '../../services/query-string';
import { device } from '../../services/device';

export default defineComponent({
    name: 'WalletView',
    components: {
    },
    data() {
        return {
            isFreePlay: false,
            italyFreeplaySessionPending: false,
            sessionRequestInProgress: false,
            showSessionPopup: false,
            currentBalance: 0,
            walletInitialSliderValue: 100,
            walletTranslations: {
                currentBalance: inversifyContainer.strings.overlays.wallet?.currentBalance,
                selectedBalance: inversifyContainer.strings.overlays.wallet?.selectedBalance,
                infoText: inversifyContainer.strings.overlays.wallet?.infoText
            },
            isSubGame: false,
            realDeviceType: device.type.realValue,
            viewportScale: 1,
            region: queryStringParams.locale as string
        };
    },
    computed: {
        currencyEUR(): ICurrencySettings { return inversifyContainer.currencySettings; },
    },
    mounted(): void {
        this.isFreePlay = userModel.freePlayBalance > 0;
        this.currentBalance = userModel.totalBalance.startBalance;
        this.isSubGame = queryStringParams.isSubGame;
        this.viewportScale = this.isSubGame && device.type.realValue === 'desktop' ? 0.7 : 1;

        eventEmitter.on('POPUP_SHOW_WALLET', this.openSessionPopup, this);
        eventEmitter.on('GLOBAL_SETTINGS_VISIBILITY_CHANGE', (visibility: boolean) => {
            if (visibility) {
                this.closeSessionPopup();
            }
            
        });
        eventEmitter.on('GAME_BEGIN', () => {
            this.currentBalance = this.isFreePlay ? userModel.freePlayBalance : userModel.visibleBalance.startBalance;
        });
        eventEmitter.on('GAME_COMPLETE', () => {
            this.currentBalance = this.isFreePlay ? userModel.freePlayBalance : userModel.visibleBalance.endBalance;
        });
        eventEmitter.on('GLOBAL_FREEPLAY_SESSION_START_ITALY', () => {
            this.italyFreeplaySessionPending = true;
            this.updateWallet(Math.min(userModel.totalBalance.endBalance, 100000));
        });
        eventEmitter.on('GLOBAL_FREEPLAY_ITALY_SESSION_READY', () => {
            inversifyContainer.cabinet.enablePurchaseButton();
            inversifyContainer.cabinet.enableStakeButtons();
        });
        eventEmitter.on('GLOBAL_FREE_PLAY_EARNED', () => {
            this.isFreePlay = true;
            this.currentBalance = userModel.freePlayBalance;
        });
        eventEmitter.on('GLOBAL_FREE_PLAY_ENDED', () => {
            this.isFreePlay = false;
            this.currentBalance = userModel.totalBalance.endBalance;
            this.walletInitialSliderValue = 100;
        });
    },
    methods: {
        updateWallet(maxbet: number): void {
            if (this.isFreePlay) {
                maxbet = Math.min(Math.max(userModel.totalBalance.endBalance, userModel.freePlayBalance), 100000);
            } else if (this.sessionRequestInProgress) {
                maxbet = userModel.totalBalance.endBalance; 
            }

            this.sendCreateSessionData(maxbet).then((response: any) => {
                this.italyFreeplaySessionPending = false;
                this.closeSessionPopup();
                userModel.setWalletData(maxbet, maxbet);
                eventEmitter.emit('GLOBAL_WALLET_UPDATED');
                eventEmitter.emit('GLOBAL_SESSION_CREATED', response);
                eventEmitter.emit('GLOBAL_FREEPLAY_ITALY_SESSION_READY');
                return;
            }).catch((error: Error) => {
                throw error;
            });
        },
        openSessionPopup(response: IGameServerResponse): void {
            this.currentBalance = this.isFreePlay ? userModel.freePlayBalance : userModel.totalBalance.endBalance;

            if (this.region === 'it-it') { // this should always be true since this view is only for IT
                if (this.italyFreeplaySessionPending) { return; }
                if (this.isFreePlay) {
                    this.updateWallet(Math.min(userModel.totalBalance.endBalance, 100000));
                    return;
                }
            }

            // Two scenarios to consider: a cash session (restore the player's chosen MaxBet) and a freeplay session
            // (MaxBet is the freeplay balance, not a player choice so keep the slider at 100%).
            const session = response.SessionStatus;
            const isCashSession = inversifyContainer.gameModel.playMode !== 'FreePlay';
            let sliderValue = 100;
            if (isCashSession && session && session.MaxBet !== 0) {
                const maxWallet = Math.min(this.currentBalance, 100000);
                sliderValue = 100 * Math.min(1, session.MaxBet / maxWallet);
            }

            this.walletInitialSliderValue = sliderValue;
            this.showSessionPopup = true;
        },
        closeSessionPopup(): void {
            this.showSessionPopup = false;
        },
        sendCreateSessionData(maxBet: number): Promise<IGameServerResponse> {
            const data = {
                UserId: userModel.userId,
                CrossCheck: userModel.crossCheck,
                MaxBet: maxBet,
                PlayMode: this.isFreePlay ? 'FreePlay' : 'Cash',
                Skin: gameConfig.engineName === 'unknown' ? 'bubble' : gameConfig.engineSkinName,
                ClientTypeId: userModel.clientTypeId
            };

            this.sessionRequestInProgress = true;
            return axios.post((`${inversifyContainer.endPoints.urls[environment].game}${'createsession'}`), data)
                .then((response: { data: IGameServerResponse }) => {
                    this.sessionRequestInProgress = false;
                    switch (response.data.ResultCode.ResultCode) {
                        case RESULT_CODES.SUCCESS:
                        case RESULT_CODES.NEW_PLAYER:
                        case RESULT_CODES.USE_FREE_PLAY_FIRST:
                            return response.data;
                        case RESULT_CODES.FREE_PLAY_AWARDED:
                            if (!gameConfig.supportsFreeplays) {
                                return response.data;
                            }
                            throw new Error('unexpected error from createsession');
                        default:
                            // inversifyContainer.frameConnection.publishNotification(response.data.ResultCode.ResultCode);
                            throw new Error('unexpected error from createsession');
                    }
                }).catch((e) => {
                    this.sessionRequestInProgress = false;
                    throw e;
                });
        }
    }
});
